insertBefore('const RULE_DEFS = {', `GAME_CATALOG.qiguo = {\n  id: "qiguo",\n  family: "qiguo",\n  title: "七國象棋",\n  short: "3～7 人 · 19×19",\n  description: "司馬光七國象戲：19×19、中央周位、七國共 119 子。支援 3～7 人合縱連橫與七國固定國序。",\n};\n\n`, 'qiguo catalog');

insertBefore('const SIDE_MODE_CONFIG = {', `RULE_DEFS.qiguo = {\n  defaults:{playerCount:7,drawMode:"country"},\n  fields:[\n    {key:"playerCount",label:"對局人數",type:"select",options:[[3,"3 人 · 3-2-2 合縱連橫"],[4,"4 人"],[5,"5 人"],[6,"6 人"],[7,"7 人 · 一人一國"]],help:"盤面始終保留七國。人數不足時依合縱連橫由部分玩家同時控制多國。"},\n    {key:"drawMode",label:"抽籤方式",type:"select",options:[["country","抽國家／聯盟（國序固定）"],["number","抽 1～N 號後依序選國"]],help:"抽國家時由伺服器隨機分配國家或聯盟；抽號碼時先隨機決定選國順序，再由玩家依號碼選擇尚未被選走的國家／聯盟。"}\n  ],\n  extraHelp:"七國固定行棋順序：秦 → 韓 → 楚 → 魏 → 齊 → 燕 → 趙。秦白、韓橘、楚紅、魏綠、齊藍、燕黑、趙紫。中央周不可移動、不可吃、不可進入。每國 17 子：將、偏、裨、砲、弓、弩、行人各一，刀二，劍與騎各四。將直斜任意距離；偏直走；裨斜走；砲隔一子吃；弓直斜四路；弩直斜五路；刀斜一步；劍直一步；騎採直一斜三長馬步；行人可直斜遠走但不能吃也不能被吃。擒將或使一國損失達 10 子會使該國失國並由勝方接管殘子；擒二將或累計吃滿 30 子者稱霸。"\n};\n\n`, 'qiguo rule defs');

