replaceBlock('function publicOpening(room) {', `function publicOpening(room) {\n  const o = room?.opening;\n  if (!o) return null;\n  const name = (id) => roomMemberById(room, id)?.name || null;\n  if (room.gameId === "qiguo") return {\n    mode:o.mode || "", phase:o.phase || "", resolved:!!o.resolved, chooserId:o.chooserId || null, chooserName:name(o.chooserId),\n    drawNumbers:Array.isArray(o.drawNumbers) ? o.drawNumbers.map((x)=>({memberId:x.memberId,name:name(x.memberId),number:x.number})) : [],\n    availableGroups:Array.isArray(o.availableGroups) ? structuredClone(o.availableGroups) : [],\n  };\n  return {\n    mode:o.mode || "", phase:o.phase || "", resolved:!!o.resolved,\n    holderId:o.holderId || null, holderName:name(o.holderId),\n    actorId:o.actorId || null, actorName:name(o.actorId),\n    chooserId:o.chooserId || null, chooserName:name(o.chooserId),\n    guessRule:o.guessRule || null,\n  };\n}`, 'public qiguo opening');

