replaceBlock('function sideName(gameId,s){', `function sideName(gameId,s){if(!s)return lang==='en'?'Pending':lang==='zh-Hans'?'待分色':'待分色';if(gameId==='qiguo'){var n={qin:'秦',han:'韓',chu:'楚',wei:'魏',qi:'齊',yan:'燕',zhao:'趙'};return (n[s]||s)+(lang==='en'?' state':'國')}if(gameId==='chess')return s==='W'?(lang==='en'?'White':lang==='zh-Hans'?'白方':'白方'):(lang==='en'?'Black':'黑方');if(gameId==='xiangqi'||gameId==='xiangqi_random'||gameId==='banqi')return s==='R'?(lang==='en'?'Red':lang==='zh-Hans'?'红方':'紅方'):(lang==='en'?'Black':'黑方');return s==='B'?(lang==='en'?'Black':'黑方'):(lang==='en'?'White':'白方')}`, 'qiguo side name');

replaceBlock('function renderPlayers(r){', `function renderPlayers(r){var el=$('players');el.textContent='';if(r.gameId==='qiguo'){(r.playerList||[]).forEach(function(p,i){var d=document.createElement('div');var active=p&&r.status==='playing'&&r.gameState&&Array.isArray(p.countries)&&p.countries.indexOf(r.gameState.turn)>=0;d.className='player-card card'+(active?' active':'');var icon=document.createElement('div');icon.className='seat-icon';icon.textContent=p&&p.countries&&p.countries.length?p.countries.map(function(c){return sideName('qiguo',c).charAt(0)}).join(''):'–';var txt=document.createElement('div');var strong=document.createElement('strong');strong.textContent=p?p.name:((lang==='en'?'Player ':'玩家 ')+(i+1)+' · '+t('emptySeat'));var sub=document.createElement('div');sub.className='small muted';if(p){var cs=(p.countries||[]).map(function(c){return sideName('qiguo',c)}).join('／');sub.textContent=(cs||((r.status==='playing')?(lang==='en'?'Eliminated':'已淘汰'):t('waiting')))+' · '+(p.connected?t('online'):t('offline'))+(p.isOwner?' · '+t('host'):'')}else sub.textContent=t('waiting');txt.appendChild(strong);txt.appendChild(sub);d.appendChild(icon);d.appendChild(txt);el.appendChild(d)});return}[[t('playerA'),r.players.host],[t('playerB'),r.players.guest]].forEach(function(pair){var d=document.createElement('div');d.className='player-card card'+(pair[1]&&r.status==='playing'&&pair[1].side===r.gameState.turn?' active':'');var icon=document.createElement('div');icon.className='seat-icon';icon.textContent=pair[1]?sideName(r.gameId,pair[1].side).charAt(0):'–';var txt=document.createElement('div');var strong=document.createElement('strong');strong.textContent=pair[1]?pair[1].name:pair[0]+' · '+t('emptySeat');var sub=document.createElement('div');sub.className='small muted';if(pair[1])sub.textContent=sideName(r.gameId,pair[1].side)+' · '+(pair[1].connected?t('online'):(t('offline')+(pair[1].offlineDeadline?' · 60s → '+t('resign'):'')))+(pair[1].isOwner?' · '+t('host'):'');else sub.textContent=t('waiting');txt.appendChild(strong);txt.appendChild(sub);d.appendChild(icon);d.appendChild(txt);el.appendChild(d)})}`, 'qiguo players UI');

